grep -q -- '"errors"' "$TMPD/m39" || die "en.json payload is wrong. Aborting."
grep -q -- '"videoPage"' "$TMPD/m39" || die "en.json payload lost 15b2. Aborting."
grep -q -- 'سياسة الخصوصية' "$TMPD/m38" || die "frontend/src/messages/ar.json payload is wrong. Aborting."
grep -q -- 'ErrorTextBridge' "$TMPD/m21" || die "AppProviders.tsx payload is wrong. Aborting."
grep -q -- 'localize(' "$TMPD/m36" || die "api.ts payload is wrong. Aborting."
grep -q -- 'useTranslations("privacy")' "$TMPD/m6" || die "privacy page payload is wrong. Aborting."
grep -q -- '!== "off"' "$TMPD/m35" || die "config.ts payload is wrong. Aborting."
grep -q -- 'useTranslations("live")' "$TMPD/m27" || die "LiveStudio.tsx payload is wrong. Aborting."
say "46 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in ${ADD[@]+"${ADD[@]}"}; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in ${ADD[@]+"${ADD[@]}"}; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in ${ADD[@]+"${ADD[@]}"}; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Part 15b3 (the rest of the site, legal pages, server errors)."
say "No backend change, no migration and no new package."
say "Languages are now on everywhere. The Vercel variable NEXT_PUBLIC_LANGUAGES"
say "is no longer needed: delete it, or set it to off to switch languages off."
say "Verify before pushing:"
say "  (cd frontend && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_lang_b3.sh --revert"
